"use client";

import { forwardRef, type ComponentProps } from "react";
import LegacyPromptBar from "../beautiful-ui/primitives/PromptBar";
import { BeautifulUIRoot } from "../beautiful-ui/BeautifulUIRoot";

export type PromptBarProps = NonNullable<ComponentProps<typeof LegacyPromptBar>>;

export const PromptBar = forwardRef<HTMLDivElement, PromptBarProps>((props, ref) => (
  <BeautifulUIRoot ref={ref}>
    <LegacyPromptBar {...props} />
  </BeautifulUIRoot>
));

PromptBar.displayName = "PromptBar";

export default PromptBar;

"use client";

import "../beautiful-ui.css";

import {
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type RefObject,
} from "react";
import { createShader, playSweep, accentChain, ACCENTS } from "glimm";
import { shapeMap, useShape } from "@/lib/shape-context";
import { FluidHoverHighlight } from "@/components/ui/fluid-hover-highlight";
import {
  useFluidHover,
  useRegisterFluidHoverItem,
  type UseFluidHoverReturn,
} from "@/hooks/use-fluid-hover";
import { useReducedMotion } from "../hooks/useReducedMotion";

/* The built-in "prism" palette is only cyan→indigo→magenta, so a sweep
 * reads as blue/purple. Build a true full-spectrum rainbow instead. */
const RAINBOW = accentChain([
  ACCENTS.red,
  ACCENTS.orange,
  ACCENTS.yellow,
  ACCENTS.green,
  ACCENTS.cyan,
  ACCENTS.blue,
  ACCENTS.purple,
]);

/* ─────────────────────────────────────────────────────────
 * PROMPT BAR
 * A composer with real controls: attach, @ data sources,
 * / commands, a model picker, dictation, and send.
 * Type @ or / to open the menus; ↑↓ + Enter to pick.
 * Uses the active BoringUI shape; legacy variants explicitly override it.
 * ───────────────────────────────────────────────────────── */

function Icon({
  children,
  size = 15,
  strokeWidth = 1.8,
}: {
  children: React.ReactNode;
  size?: number;
  strokeWidth?: number;
}) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      {children}
    </svg>
  );
}

const GLYPHS: Record<string, React.ReactNode> = {
  clip: (
    <path d="m21.4 11.05-9.19 9.19a6 6 0 0 1-8.49-8.49l8.57-8.57A4 4 0 1 1 18 8.84l-8.59 8.57a2 2 0 0 1-2.83-2.83l8.49-8.48" />
  ),
  chart: <path d="M4 20V10M10 20V4M16 20v-7M22 20H2" />,
  layers: (
    <g>
      <path d="M12 2 2 7l10 5 10-5-10-5z" />
      <path d="M2 17l10 5 10-5M2 12l10 5 10-5" />
    </g>
  ),
  globe: (
    <g>
      <circle cx="12" cy="12" r="10" />
      <path d="M2 12h20M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" />
    </g>
  ),
};

/* real product marks, inline so the file stays self-contained */
const BRANDS: Record<string, React.ReactNode> = {
  figma: (
    <svg width="11" height="16" viewBox="0 0 38 57" aria-hidden="true">
      <path d="M9.5 57A9.5 9.5 0 0 0 19 47.5V38H9.5a9.5 9.5 0 0 0 0 19z" fill="#0ACF83" />
      <path d="M0 28.5A9.5 9.5 0 0 1 9.5 19H19v19H9.5A9.5 9.5 0 0 1 0 28.5z" fill="#A259FF" />
      <path d="M0 9.5A9.5 9.5 0 0 1 9.5 0H19v19H9.5A9.5 9.5 0 0 1 0 9.5z" fill="#F24E1E" />
      <path d="M19 0h9.5a9.5 9.5 0 1 1 0 19H19V0z" fill="#FF7262" />
      <path d="M38 28.5a9.5 9.5 0 1 1-19 0 9.5 9.5 0 0 1 19 0z" fill="#1ABCFE" />
    </svg>
  ),
  slack: (
    <svg width="15" height="15" viewBox="0 0 127 127" aria-hidden="true">
      <path
        d="M27.2 80c0 7.3-5.9 13.2-13.2 13.2C6.7 93.2.8 87.3.8 80c0-7.3 5.9-13.2 13.2-13.2h13.2V80zm6.6 0c0-7.3 5.9-13.2 13.2-13.2 7.3 0 13.2 5.9 13.2 13.2v33c0 7.3-5.9 13.2-13.2 13.2-7.3 0-13.2-5.9-13.2-13.2V80z"
        fill="#E01E5A"
      />
      <path
        d="M47 27.2c-7.3 0-13.2-5.9-13.2-13.2C33.8 6.7 39.7.8 47 .8c7.3 0 13.2 5.9 13.2 13.2v13.2H47zm0 6.7c7.3 0 13.2 5.9 13.2 13.2 0 7.3-5.9 13.2-13.2 13.2H13.9C6.6 60.3.7 54.4.7 47.1c0-7.3 5.9-13.2 13.2-13.2H47z"
        fill="#36C5F0"
      />
      <path
        d="M99.9 47.1c0-7.3 5.9-13.2 13.2-13.2 7.3 0 13.2 5.9 13.2 13.2 0 7.3-5.9 13.2-13.2 13.2H99.9V47.1zm-6.6 0c0 7.3-5.9 13.2-13.2 13.2-7.3 0-13.2-5.9-13.2-13.2V13.9C66.9 6.6 72.8.7 80.1.7c7.3 0 13.2 5.9 13.2 13.2v33.2z"
        fill="#2EB67D"
      />
      <path
        d="M80.1 99.8c7.3 0 13.2 5.9 13.2 13.2 0 7.3-5.9 13.2-13.2 13.2-7.3 0-13.2-5.9-13.2-13.2V99.8h13.2zm0-6.6c-7.3 0-13.2-5.9-13.2-13.2 0-7.3 5.9-13.2 13.2-13.2h33.1c7.3 0 13.2 5.9 13.2 13.2 0 7.3-5.9 13.2-13.2 13.2H80.1z"
        fill="#ECB22E"
      />
    </svg>
  ),
  gmail: (
    <svg width="15" height="12" viewBox="0 0 256 193" aria-hidden="true">
      <path
        d="M58.182 192.05V93.14L27.507 65.077 0 49.504v125.091c0 9.658 7.825 17.455 17.455 17.455h40.727Z"
        fill="#4285F4"
      />
      <path
        d="M197.818 192.05h40.727c9.659 0 17.455-7.826 17.455-17.455V49.505l-31.156 17.837-27.026 25.798v98.91Z"
        fill="#34A853"
      />
      <path
        d="m58.182 93.14-4.174-38.647 4.174-36.989L128 69.868l69.818-52.364 4.669 34.992-4.669 40.644L128 145.504 58.182 93.14Z"
        fill="#EA4335"
      />
      <path
        d="M197.818 17.504V93.14L256 49.504V26.231c0-21.585-24.64-33.89-41.89-20.945l-16.292 12.218Z"
        fill="#FBBC04"
      />
      <path
        d="m0 49.504 26.759 20.07L58.182 93.14V17.504L41.89 5.286C24.61-7.66 0 4.646 0 26.23v23.273Z"
        fill="#C5221F"
      />
    </svg>
  ),
};

type Source = {
  key: string;
  name: string;
  desc: string;
  glyph?: string;
  brand?: string;
  attach?: boolean;
  connect?: boolean;
};

const SOURCES: Source[] = [
  {
    key: "attach",
    name: "Add photos & files",
    desc: "Upload from your computer",
    glyph: "clip",
    attach: true,
  },
  { key: "scoop", name: "Scoop Data", desc: "Sales & churn metrics", glyph: "chart" },
  { key: "flavors", name: "Flavor records", desc: "26 makers, tags, links", glyph: "layers" },
  { key: "web", name: "Web search", desc: "Real-time news and info", glyph: "globe" },
  { key: "figma", name: "Figma", desc: "Design-to-code workflows", brand: "figma" },
  { key: "slack", name: "Slack", desc: "Read and manage Slack", brand: "slack" },
  { key: "gmail", name: "Gmail", desc: "Read and manage Gmail", brand: "gmail", connect: true },
];

const COMMANDS = [
  { key: "compare", name: "/compare", desc: "Flavor vs. last summer" },
  { key: "churn-plan", name: "/churn-plan", desc: "Draft a churn schedule" },
  { key: "restock", name: "/restock", desc: "Build a reorder list" },
  { key: "draft-email", name: "/draft-email", desc: "Write a supplier email" },
  { key: "summarize", name: "/summarize", desc: "Digest the thread so far" },
];

const MODELS = [
  { key: "sprinkles-5", name: "Sprinkles 5", tag: "Flagship" },
  { key: "vanilla-1", name: "Vanilla 1", tag: "Basic" },
  { key: "freezer-burn", name: "Freezer Burn 0.4", tag: "Stale" },
];

const FILES = ["flavor-chart.png", "summer-menu.pdf", "pos-export.csv"];
const DICTATION = "Compare pistachio weekends to last summer";

/* self-running demo: walk the @ menu, then the / menu, and repeat.
 * Any pointer or key interaction hands control to the user. */
const AUTO_STEPS: {
  draft: string;
  active?: number;
  connect?: boolean;
  modelOpen?: boolean;
  model?: string;
  hold: number;
}[] = [
  { draft: "", connect: false, model: "vanilla-1", hold: 1100 },
  { draft: "@", active: 0, hold: 900 },
  { draft: "@", active: 1, hold: 620 },
  { draft: "@", active: 4, hold: 620 },
  { draft: "@", active: 6, hold: 700 },
  { draft: "@", active: 6, connect: true, hold: 1000 },
  { draft: "", hold: 700 },
  { draft: "/", active: 0, hold: 900 },
  { draft: "/", active: 1, hold: 620 },
  { draft: "/", active: 3, hold: 1000 },
  { draft: "", hold: 800 },
  // open the model picker and upgrade to the flagship → rainbow sweep
  { draft: "", modelOpen: true, hold: 1200 },
  { draft: "", model: "sprinkles-5", hold: 2400 },
  { draft: "", hold: 900 },
];

/* the last @word or /word being typed, if any */
function parseToken(draft: string): { kind: "at" | "slash"; query: string; start: number } | null {
  const match = /(^|\s)([@/])([\w-]*)$/.exec(draft);
  if (!match) return null;
  return {
    kind: match[2] === "@" ? "at" : "slash",
    query: match[3].toLowerCase(),
    start: match.index + match[1].length,
  };
}

function SuggestionRow({
  index,
  registerItem,
  ...props
}: HTMLAttributes<HTMLDivElement> & {
  index: number;
  registerItem: UseFluidHoverReturn["registerItem"];
}) {
  const ref = useRef<HTMLDivElement>(null);
  useRegisterFluidHoverItem(registerItem, index, ref);
  return <div ref={ref} {...props} />;
}

function ModelMenuItem({
  index,
  registerItem,
  rowRefs,
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement> & {
  index: number;
  registerItem: UseFluidHoverReturn["registerItem"];
  rowRefs: RefObject<(HTMLButtonElement | null)[]>;
}) {
  const ref = useRef<HTMLButtonElement>(null);
  const setRef = useCallback(
    (element: HTMLButtonElement | null) => {
      ref.current = element;
      rowRefs.current[index] = element;
    },
    [index, rowRefs],
  );
  useRegisterFluidHoverItem(registerItem, index, ref);
  return <button ref={setRef} data-model-option-index={index} {...props} />;
}

export interface PromptBarProps {
  /** Optional legacy shape override. Omitted, follows the active ShapeProvider. */
  variant?: string;
  demo?: boolean;
  tall?: boolean;
  placeholder?: string;
  onSend?: (text: string) => void;
  onConnect?: (source: string, connected: boolean) => void;
  onModelChange?: (model: string) => void;
}

export default function PromptBar({
  variant,
  demo = false,
  tall = false,
  placeholder,
  onSend,
  onConnect,
  onModelChange,
}: PromptBarProps) {
  const globalShape = useShape();
  const shape =
    variant === "Pill" ? shapeMap.pill : variant === "Rounded" ? shapeMap.rounded : globalShape;
  const reducedMotion = useReducedMotion();
  const suggestionListId = useId();
  const modelMenuId = useId();
  const pill = shape.variant === "pill";
  const [draft, setDraft] = useState("");
  const [dismissed, setDismissed] = useState(false);
  const [plusOpen, setPlusOpen] = useState(false);
  const [modelOpen, setModelOpen] = useState(false);
  const [model, setModel] = useState(MODELS[1]);
  const [attachments, setAttachments] = useState<string[]>([]);
  const [connected, setConnected] = useState(false);
  const [rememberedActive, setRememberedActive] = useState(0);
  const [listening, setListening] = useState(false);
  const [auto, setAuto] = useState(demo);
  const [autoStep, setAutoStep] = useState(0);
  const [expanded, setExpanded] = useState(false);
  const wide = expanded || tall;
  const [modelMenuLeft, setModelMenuLeft] = useState(0);
  const [modelMenuBottom, setModelMenuBottom] = useState(0);
  const composerAnchorRef = useRef<HTMLDivElement>(null);
  const controlsRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const measureRef = useRef<HTMLSpanElement>(null);
  const modelRef = useRef<HTMLButtonElement>(null);
  const suggestionMenuRef = useRef<HTMLDivElement>(null);
  const modelMenuRef = useRef<HTMLDivElement>(null);
  const modelMouseInside = useRef(false);
  const modelRowRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const glimmRef = useRef<HTMLCanvasElement>(null);
  const shaderRef = useRef<ReturnType<typeof createShader> | null>(null);
  const sweepingRef = useRef(false);
  const suggestionHover = useFluidHover(suggestionMenuRef, { gapClick: false });
  const modelHover = useFluidHover(modelMenuRef, { gapClick: false });
  const setActive = suggestionHover.setActiveIndex;
  const modelHovered = modelHover.activeIndex;

  useEffect(() => {
    if (reducedMotion) setAuto(false);
  }, [reducedMotion]);

  /* hand control to the user: stop the demo loop, and when they aim at
   * the input itself, clear the demo's leftover draft for a clean start */
  const takeOver = (event: { target: EventTarget | null }) => {
    setAuto(false);
    if (auto && event.target === inputRef.current) setDraft("");
  };

  const takeOverInput = () => {
    if (auto) setDraft("");
    setAuto(false);
  };

  const token = dismissed ? null : parseToken(draft);
  const menu: "at" | "slash" | null = plusOpen ? "at" : (token?.kind ?? null);
  const query = plusOpen ? "" : (token?.query ?? "");

  const rows: { key: string; name: string; desc: string }[] =
    menu === "at"
      ? SOURCES.filter((s) => s.name.toLowerCase().includes(query))
      : menu === "slash"
        ? COMMANDS.filter((c) => c.name.slice(1).startsWith(query))
        : [];
  const active = Math.min(
    suggestionHover.activeIndex ?? rememberedActive,
    Math.max(0, rows.length - 1),
  );

  useEffect(() => {
    if (suggestionHover.activeIndex !== null) setRememberedActive(suggestionHover.activeIndex);
  }, [suggestionHover.activeIndex]);

  useEffect(() => {
    setRememberedActive(0);
    setActive(null);
  }, [menu, query, setActive]);

  // The popups mount conditionally while their hover controllers stay alive.
  // Opening invalidates geometry; row registration/resize handles later reflow.
  useLayoutEffect(() => {
    if (menu) suggestionHover.remeasure();
  }, [menu, suggestionHover.remeasure]);

  const modelIndex = MODELS.findIndex((m) => m.key === model.key);
  useLayoutEffect(() => {
    if (modelOpen) modelHover.remeasure();
  }, [modelOpen, modelHover.remeasure]);

  /* The menu is outside the clipped composer, so align it to the model
   * trigger by measurement instead of pinning it to the far-right edge. */
  useLayoutEffect(() => {
    if (!modelOpen || !composerAnchorRef.current || !modelRef.current) return;
    const anchorRect = composerAnchorRef.current.getBoundingClientRect();
    const triggerRect = modelRef.current.getBoundingClientRect();
    setModelMenuLeft(
      Math.max(0, Math.min(triggerRect.left - anchorRect.left, anchorRect.width - 176)),
    );
    setModelMenuBottom(anchorRect.bottom - triggerRect.top + 8);
  }, [modelOpen, wide, model.name]);

  useEffect(() => {
    if (!modelOpen) {
      modelMouseInside.current = false;
      modelHover.setActiveIndex(null);
      return;
    }
    if (auto) return;
    const frame = requestAnimationFrame(() =>
      modelRowRefs.current[modelIndex]?.focus({ preventScroll: true }),
    );
    return () => cancelAnimationFrame(frame);
  }, [auto, modelIndex, modelOpen, modelHover.setActiveIndex]);

  /* Build the shader with a pinned hue phase. createShader seeds its
   * internal hueShift from Math.random(), which made the sweep a different
   * colour on every reload — pin it so the rainbow is identical each time. */
  const makeShader = () => {
    const canvas = glimmRef.current;
    if (!canvas) return null;
    const random = Math.random;
    Math.random = () => 0;
    try {
      return createShader({
        canvas,
        palette: RAINBOW,
        direction: "ltr",
        bandTight: 10,
        swellAmount: 0.85,
      });
    } finally {
      Math.random = random;
    }
  };

  /* Glimm shader lives inside the composer, invisible at rest. Selecting
   * the flagship model fires a one-shot rainbow sweep across the interior. */
  useEffect(() => {
    if (reducedMotion) return;
    shaderRef.current = makeShader();
    return () => {
      shaderRef.current?.destroy();
      shaderRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reducedMotion]);

  const celebrate = () => {
    if (sweepingRef.current) return;
    if (reducedMotion) return;
    // Recreate the shader per sweep so uTime restarts at 0 — the hue phase
    // (which drifts with time) is then identical on every trigger.
    shaderRef.current?.destroy();
    const shader = makeShader();
    shaderRef.current = shader;
    if (!shader) return;
    sweepingRef.current = true;
    const sweep = playSweep(shader, {
      palette: RAINBOW,
      direction: "ltr",
      sweepMs: 240,
      outroMs: 80,
      peakAlpha: 1.3,
      bandTight: 10,
      brightness: 1.4,
      swellAmount: 1,
      waveSpeed: 1.8,
      easing: "easeOutExpo",
    });
    void sweep.done.finally(() => {
      sweepingRef.current = false;
    });
  };

  const selectModel = (next: (typeof MODELS)[number], notify = true) => {
    setModel(next);
    setModelOpen(false);
    if (notify) onModelChange?.(next.key);
    if (next.key === "sprinkles-5") celebrate();
  };

  /* autoplay: apply the current step, then advance after its hold */
  useEffect(() => {
    if (!auto || reducedMotion) return;
    const step = AUTO_STEPS[autoStep % AUTO_STEPS.length];
    setDraft(step.draft);
    if (step.active !== undefined) setActive(step.active);
    if (step.connect !== undefined) setConnected(step.connect);
    if (step.modelOpen !== undefined) setModelOpen(step.modelOpen);
    if (step.model) {
      const next = MODELS.find((m) => m.key === step.model);
      if (next) selectModel(next, false);
    }
    const t = setTimeout(() => setAutoStep((s) => s + 1), step.hold);
    return () => clearTimeout(t);
  }, [auto, autoStep, reducedMotion]);

  /* dictation resolves after a beat, like a real transcript landing */
  useEffect(() => {
    if (!listening) return;
    const t = setTimeout(() => {
      setDraft((current) => (current ? `${current.trimEnd()} ${DICTATION}` : DICTATION));
      setListening(false);
      inputRef.current?.focus();
    }, 2200);
    return () => clearTimeout(t);
  }, [listening]);

  /* Move wrapped text above the controls, then grow to a compact maximum. */
  useLayoutEffect(() => {
    const input = inputRef.current;
    const controls = controlsRef.current;
    const measure = measureRef.current;
    const modelButton = modelRef.current;
    if (!input || !controls || !measure || !modelButton) return;

    const fixedControlsWidth = 28 * 3 + modelButton.offsetWidth;
    const inlineGaps = 4 * 4;
    const inlineInputWidth = controls.clientWidth - fixedControlsWidth - inlineGaps;
    const needsFullWidth = draft.includes("\n") || measure.offsetWidth + 8 > inlineInputWidth;
    if (needsFullWidth !== expanded) {
      setExpanded(needsFullWidth);
    }

    const minHeight = 28;
    const maxHeight = 100;
    input.style.height = "0px";
    const contentHeight = input.scrollHeight;
    input.style.height = `${Math.min(Math.max(contentHeight, minHeight), maxHeight)}px`;
    input.style.overflowY = contentHeight > maxHeight ? "auto" : "hidden";
  }, [draft, expanded]);

  /* clicking anywhere outside the composer closes the open menus */
  useEffect(() => {
    if (!modelOpen && !plusOpen) return;
    const close = (event: PointerEvent) => {
      if (!(event.target as Element).closest("[data-promptbar]")) {
        setModelOpen(false);
        setPlusOpen(false);
      }
    };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [modelOpen, plusOpen]);

  const closeMenus = () => {
    setPlusOpen(false);
    setModelOpen(false);
  };

  const closeModelMenu = (restoreFocus = false) => {
    setModelOpen(false);
    if (restoreFocus) requestAnimationFrame(() => modelRef.current?.focus());
  };

  const focusModelRow = (index: number) => {
    const bounded = (index + MODELS.length) % MODELS.length;
    modelHover.setActiveIndex(bounded);
    modelRowRefs.current[bounded]?.focus({ preventScroll: true });
  };

  const pick = (row: { key: string; name: string }) => {
    const source = SOURCES.find((s) => s.key === row.key);
    if (source?.attach) {
      setAttachments((current) => [...current, FILES[current.length % FILES.length]]);
      if (token) setDraft(draft.slice(0, token.start));
    } else if (menu === "at") {
      setDraft(`${token ? draft.slice(0, token.start) : draft}@${row.name} `);
    } else {
      setDraft(`${token ? draft.slice(0, token.start) : draft}${row.name} `);
    }
    setPlusOpen(false);
    setDismissed(false);
    inputRef.current?.focus();
  };

  const canSend = draft.trim().length > 0 || attachments.length > 0;
  const send = () => {
    if (!canSend) return;
    onSend?.(draft.trim());
    setDraft("");
    setAttachments([]);
    closeMenus();
  };

  return (
    <div
      data-promptbar
      className={demo ? "flex min-h-[384px] w-full max-w-105 flex-col justify-end pb-8" : "w-full"}
      onPointerDownCapture={takeOver}
      onKeyDownCapture={takeOver}
    >
      {/* composer is the anchor — menus grow up from its top edge */}
      <div ref={composerAnchorRef} className="relative">
        {/* ── @ / slash menu ─────────────────────────────── */}
        {menu && (
          <div
            ref={suggestionMenuRef}
            id={suggestionListId}
            role="listbox"
            aria-label={menu === "at" ? "Sources and files" : "Commands"}
            {...suggestionHover.handlers}
            onKeyDown={(event) => {
              if (event.key !== "Escape") return;
              event.preventDefault();
              setDismissed(true);
              closeMenus();
              inputRef.current?.focus();
            }}
            className={`absolute inset-x-0 bottom-full z-10 mb-2 ${shape.container} bg-[var(--surface)] p-1 shadow-[var(--shadow-raised)]`}
            style={{
              animation: reducedMotion
                ? undefined
                : "pop-in 160ms cubic-bezier(0.23,1,0.32,1) both",
              transformOrigin: "bottom center",
            }}
          >
            <FluidHoverHighlight hover={suggestionHover} className={shape.item} />
            {rows.map((row, i) => {
              const source = menu === "at" ? SOURCES.find((s) => s.key === row.key) : undefined;
              return (
                <SuggestionRow
                  key={row.key}
                  index={i}
                  registerItem={suggestionHover.registerItem}
                  onFocus={() => setActive(i)}
                  className={`relative z-10 flex items-center ${shape.item}`}
                >
                  <button
                    id={`${suggestionListId}-option-${i}`}
                    type="button"
                    role="option"
                    aria-selected={i === active}
                    tabIndex={-1}
                    onMouseDown={(event) => event.preventDefault()}
                    onClick={() => pick(row)}
                    className={`flex h-9 min-w-0 flex-1 items-center gap-2.5 ${shape.item} px-2 text-left transition-transform duration-80 active:scale-[0.98]`}
                  >
                    {source ? (
                      <span className="flex size-5.5 shrink-0 items-center justify-center text-[var(--ink-2)]">
                        {source.brand ? (
                          BRANDS[source.brand]
                        ) : (
                          <Icon size={15}>{GLYPHS[source.glyph ?? "clip"]}</Icon>
                        )}
                      </span>
                    ) : null}
                    <span className="shrink-0 text-[12px] font-medium text-[var(--ink)]">
                      {row.name}
                    </span>
                    <span className="min-w-0 flex-1 truncate text-[12px] text-[var(--ink-3)]">
                      {row.desc}
                    </span>
                  </button>
                  {source?.connect ? (
                    <button
                      type="button"
                      aria-label={`${connected ? "Disconnect" : "Connect"} ${source.name}`}
                      aria-pressed={connected}
                      onMouseDown={(event) => event.preventDefault()}
                      onClick={() => {
                        const next = !connected;
                        setConnected(next);
                        onConnect?.(source.key, next);
                      }}
                      className={`mr-2 shrink-0 ${shape.button} text-[12px] font-medium transition-[color,transform] duration-80 active:scale-[0.98] ${
                        connected
                          ? "text-[var(--green)]"
                          : "text-[var(--bui-focus)] hover:underline"
                      }`}
                    >
                      {connected ? "Connected" : "Connect"}
                    </button>
                  ) : null}
                </SuggestionRow>
              );
            })}
            {rows.length === 0 && (
              <div className="flex h-9 items-center px-2 text-[12px] text-[var(--ink-3)]">
                No matches for “{query}”
              </div>
            )}
            <div className="mt-1 border-t border-[var(--line)]/40 px-2 pt-1.5 pb-1 text-[11px] text-[var(--ink-3)]">
              {menu === "at" ? "Type to search sources & files" : "Type to search commands"}
            </div>
          </div>
        )}

        {/* ── model menu ─────────────────────────────────── */}
        {modelOpen && (
          <div
            ref={modelMenuRef}
            id={modelMenuId}
            role="menu"
            aria-label="Model"
            {...modelHover.handlers}
            onMouseEnter={() => {
              modelMouseInside.current = true;
              modelHover.handlers.onMouseEnter();
            }}
            onMouseLeave={() => {
              modelMouseInside.current = false;
              modelHover.handlers.onMouseLeave();
              const focused = document.activeElement;
              if (
                focused instanceof HTMLElement &&
                modelMenuRef.current?.contains(focused) &&
                focused.matches(":focus-visible")
              ) {
                const index = focused.getAttribute("data-model-option-index");
                if (index !== null) modelHover.setActiveIndex(Number(index));
              }
            }}
            onBlurCapture={(event) => {
              if (
                !modelMenuRef.current?.contains(event.relatedTarget) &&
                !modelMouseInside.current
              ) {
                modelHover.setActiveIndex(null);
              }
            }}
            className={`absolute z-10 w-44 ${shape.container} bg-[var(--surface)] p-1 shadow-[var(--shadow-raised)]`}
            style={{
              left: modelMenuLeft,
              bottom: modelMenuBottom,
              animation: reducedMotion
                ? undefined
                : "pop-in 160ms cubic-bezier(0.23,1,0.32,1) both",
              transformOrigin: "bottom left",
            }}
          >
            <FluidHoverHighlight hover={modelHover} className={shape.item} />
            {MODELS.map((m, i) => (
              <ModelMenuItem
                key={m.key}
                index={i}
                registerItem={modelHover.registerItem}
                rowRefs={modelRowRefs}
                type="button"
                role="menuitemradio"
                aria-checked={m.key === model.key}
                tabIndex={i === (modelHovered ?? modelIndex) ? 0 : -1}
                onMouseDown={(event) => event.preventDefault()}
                onFocus={() => modelHover.setActiveIndex(i)}
                onKeyDown={(event) => {
                  if (event.key === "ArrowDown") {
                    event.preventDefault();
                    focusModelRow(i + 1);
                  } else if (event.key === "ArrowUp") {
                    event.preventDefault();
                    focusModelRow(i - 1);
                  } else if (event.key === "Home") {
                    event.preventDefault();
                    focusModelRow(0);
                  } else if (event.key === "End") {
                    event.preventDefault();
                    focusModelRow(MODELS.length - 1);
                  } else if (event.key === "Escape") {
                    event.preventDefault();
                    closeModelMenu(true);
                  }
                }}
                onClick={() => {
                  selectModel(m);
                  requestAnimationFrame(() => modelRef.current?.focus());
                }}
                className={`relative z-10 flex h-7.5 w-full items-center gap-2 ${shape.item} px-2 text-left transition-transform duration-80 active:scale-[0.98]`}
              >
                <span className="min-w-0 flex-1 truncate text-[12px] font-medium text-[var(--ink)]">
                  {m.name}
                </span>
                <span className="shrink-0 text-[11px] text-[var(--ink-3)]">{m.tag}</span>
                <span
                  className={`shrink-0 text-[var(--ink)] ${m.key === model.key ? "" : "invisible"}`}
                >
                  <Icon size={13} strokeWidth={2.5}>
                    <path d="M20 6L9 17l-5-5" />
                  </Icon>
                </span>
              </ModelMenuItem>
            ))}
          </div>
        )}

        {/* ── composer ───────────────────────────────────── */}
        <div
          data-bui-input-group=""
          className={`relative isolate flex flex-col overflow-hidden ${shape.container} bg-[var(--surface)] shadow-surface-2 transition-[border-radius] duration-160 ${
            tall ? "gap-2.5 p-3.5" : "gap-1.5 p-1.5"
          }`}
          style={{ outlineColor: "var(--border)" }}
        >
          {/* rainbow glimm sweep — plays across the interior on model change.
            explicit w/h: a <canvas> is a replaced element and won't stretch
            to inset-0 alone, which feeds back into the shader's ResizeObserver. */}
          <canvas
            ref={glimmRef}
            aria-hidden="true"
            className="pointer-events-none absolute inset-0 -z-10 h-full w-full"
            style={{ borderRadius: "inherit" }}
          />
          <span
            ref={measureRef}
            aria-hidden="true"
            className="pointer-events-none absolute invisible whitespace-pre text-[13px] leading-[18px]"
          >
            {draft}
          </span>

          {attachments.length > 0 && (
            <div className={`flex flex-wrap gap-1.5 pt-0.5 ${pill ? "px-1" : "px-0.5"}`}>
              {attachments.map((file, i) => (
                <span
                  key={`${file}-${i}`}
                  className={`flex h-6.5 items-center gap-1.5 ${shape.item} bg-[var(--field)] py-1 pr-1 pl-1.5 text-[11px] text-[var(--ink-2)] shadow-[var(--shadow-hairline)]`}
                  style={{
                    animation: reducedMotion
                      ? undefined
                      : "pop-in 160ms cubic-bezier(0.23,1,0.32,1) both",
                  }}
                >
                  <Icon size={12}>
                    <g>
                      <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                      <path d="M14 2v6h6" />
                    </g>
                  </Icon>
                  <span className="max-w-36 truncate">{file}</span>
                  <button
                    type="button"
                    aria-label={`Remove ${file}`}
                    onClick={() => setAttachments((current) => current.filter((_, j) => j !== i))}
                    className={`-my-1 flex size-6 items-center justify-center ${shape.button} text-[var(--ink-3)] transition-[background-color,color,transform] duration-80 hover:bg-[var(--line)]/70 hover:text-[var(--ink)] active:scale-[0.98]`}
                  >
                    <Icon size={10} strokeWidth={2.5}>
                      <path d="M18 6L6 18M6 6l12 12" />
                    </Icon>
                  </button>
                </span>
              ))}
            </div>
          )}

          <div
            ref={controlsRef}
            className={`grid items-end gap-x-1 gap-y-1.5 ${
              wide
                ? "grid-cols-[28px_auto_minmax(0,1fr)_28px_28px]"
                : "grid-cols-[28px_minmax(0,1fr)_auto_28px_28px]"
            }`}
          >
            <button
              type="button"
              aria-label="Add attachments and sources"
              aria-expanded={plusOpen}
              aria-controls={suggestionListId}
              onClick={() => {
                setModelOpen(false);
                setPlusOpen((current) => !current);
                inputRef.current?.focus();
              }}
              className={`flex size-7 shrink-0 items-center justify-center justify-self-start ${shape.button} text-[var(--ink-3)] transition-[background-color,color,transform] duration-160 hover:bg-[var(--hover)] hover:text-[var(--ink)] active:scale-[0.98] ${plusOpen ? "bg-[var(--hover)] text-[var(--ink)]" : ""} ${wide ? "col-start-1 row-start-2" : "col-start-1 row-start-1"}`}
            >
              <Icon size={16} strokeWidth={2}>
                <path d="M12 5v14M5 12h14" />
              </Icon>
            </button>

            <textarea
              ref={inputRef}
              rows={1}
              value={draft}
              onFocus={takeOverInput}
              onChange={(event) => {
                setDraft(event.target.value);
                setDismissed(false);
                setPlusOpen(false);
              }}
              onKeyDown={(event) => {
                if (menu && rows.length > 0) {
                  if (event.key === "ArrowDown" || event.key === "ArrowUp") {
                    event.preventDefault();
                    setActive(
                      (current) =>
                        ((current ?? active) + (event.key === "ArrowDown" ? 1 : rows.length - 1)) %
                        rows.length,
                    );
                    return;
                  }
                  if (event.key === "Home" || event.key === "End") {
                    event.preventDefault();
                    setActive(event.key === "Home" ? 0 : rows.length - 1);
                    return;
                  }
                  if ((event.key === "Enter" && !event.shiftKey) || event.key === "Tab") {
                    event.preventDefault();
                    pick(rows[active]);
                    return;
                  }
                }
                if (event.key === "Escape") {
                  setDismissed(true);
                  closeMenus();
                  return;
                }
                if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
                  event.preventDefault();
                  send();
                }
              }}
              placeholder={listening ? "Listening…" : (placeholder ?? "Write a message…")}
              aria-label="Prompt"
              aria-expanded={Boolean(menu)}
              aria-controls={menu ? suggestionListId : undefined}
              aria-activedescendant={
                menu && rows.length > 0 ? `${suggestionListId}-option-${active}` : undefined
              }
              aria-autocomplete="list"
              className={`${tall ? "min-h-[68px] px-2 py-2 text-[14px] leading-5" : "min-h-7 px-1 py-[5px] text-[13px] leading-[18px]"} min-w-0 w-full resize-none appearance-none rounded-none border-0 bg-transparent text-[var(--ink)] shadow-none outline-none [overflow-wrap:anywhere] placeholder:text-[var(--ink-3)] ${
                wide ? "col-span-full col-start-1 row-start-1" : "col-start-2 row-start-1"
              }`}
            />

            {/* model picker */}
            <button
              ref={modelRef}
              type="button"
              aria-expanded={modelOpen}
              aria-controls={modelMenuId}
              aria-haspopup="menu"
              aria-label="Choose model"
              onClick={() => {
                setPlusOpen(false);
                setModelOpen((current) => !current);
              }}
              onKeyDown={(event) => {
                if (event.key === "ArrowDown") {
                  event.preventDefault();
                  setPlusOpen(false);
                  setModelOpen(true);
                } else if (event.key === "Escape" && modelOpen) {
                  event.preventDefault();
                  closeModelMenu(true);
                }
              }}
              className={`flex h-7 shrink-0 items-center gap-1 ${shape.button} px-1.5 text-[12px] font-medium text-[var(--ink-2)] transition-[background-color,color,transform] duration-160 hover:bg-[var(--hover)] hover:text-[var(--ink)] active:scale-[0.98] ${wide ? "col-start-2 row-start-2 justify-self-start" : "col-start-3 row-start-1"}`}
            >
              {model.name}
              <span className="text-[var(--ink-3)]">
                <Icon size={11} strokeWidth={2.4}>
                  <path d="M6 9l6 6 6-6" />
                </Icon>
              </span>
            </button>

            {/* dictation */}
            <button
              type="button"
              aria-label={listening ? "Stop dictation" : "Start dictation"}
              aria-pressed={listening}
              onClick={() => setListening((current) => !current)}
              className={`flex size-7 shrink-0 items-center justify-center ${shape.button} transition-[background-color,color,transform] duration-160 active:scale-[0.98] ${listening ? "bg-[var(--bui-focus-tint)] text-[var(--bui-focus)]" : "text-[var(--ink-3)] hover:bg-[var(--hover)] hover:text-[var(--ink)]"} ${wide ? "col-start-4 row-start-2" : "col-start-4 row-start-1"}`}
            >
              {listening ? (
                <span className="flex h-3.5 items-center gap-[2.5px]">
                  {[0, 1, 2].map((i) => (
                    <span
                      key={i}
                      className="w-[2.5px] rounded-full bg-current"
                      style={{
                        height: "100%",
                        animation: reducedMotion
                          ? undefined
                          : `eq-bounce 240ms ease-in-out ${i * 80}ms infinite`,
                      }}
                    />
                  ))}
                </span>
              ) : (
                <Icon size={15} strokeWidth={2}>
                  <g>
                    <path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3z" />
                    <path d="M19 10v2a7 7 0 0 1-14 0v-2M12 19v3" />
                  </g>
                </Icon>
              )}
            </button>

            {/* send */}
            <button
              type="button"
              aria-label="Send prompt"
              disabled={!canSend}
              onClick={send}
              className={`flex size-7 shrink-0 items-center justify-center ${shape.button} transition-[background-color,color,transform] duration-160 enabled:active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-60 ${wide ? "col-start-5 row-start-2" : "col-start-5 row-start-1"}`}
              style={{
                background: canSend ? "var(--ink)" : "var(--line-strong)",
                color: canSend ? "var(--surface)" : "var(--ink-2)",
              }}
            >
              <Icon size={16} strokeWidth={2.4}>
                <path d="M12 19V5M5 12l7-7 7 7" />
              </Icon>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import "./beautiful-ui.css";
import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { SurfaceProvider, useSurface } from "@/lib/surface-context";
import { useShapeVariant } from "@/lib/shape-context";

export type BeautifulUIRootProps = HTMLAttributes<HTMLDivElement>;

type AdapterStyle = CSSProperties & Record<`--${string}`, string | number>;

function clampSurface(level: number) {
  return Math.max(1, Math.min(8, level));
}

function createAdapterStyle(
  substrate: number,
  surface: number,
  style?: CSSProperties,
): AdapterStyle {
  const inset = clampSurface(substrate + 1);
  const overlay = clampSurface(surface + 2);
  const raisedOverlay = clampSurface(surface + 4);

  return {
    "--page": `var(--surface-${substrate})`,
    "--canvas": `var(--surface-${substrate})`,
    "--surface": `var(--surface-${surface})`,
    "--inset": `var(--surface-${inset})`,
    "--tooltip-bg": `var(--surface-${overlay})`,
    "--overlay-surface": `var(--surface-${overlay})`,
    "--overlay-raised": `var(--surface-${raisedOverlay})`,
    ...style,
  };
}

function useBeautifulUIScope(offset = 2) {
  const substrate = useSurface();
  const surface = clampSurface(substrate + offset);
  const shape = useShapeVariant();

  return {
    shape,
    substrate,
    surface,
    style: createAdapterStyle(substrate, surface),
  };
}

/**
 * Internal compatibility boundary for the adapted primitives. It has no layout
 * box of its own: public components use it internally so consumers inherit the
 * active BoringUI theme, surface level, and radius mode without a wrapper.
 */
export const BeautifulUIRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", "contents", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIRoot.displayName = "BeautifulUIRoot";

/** Applies the same BoringUI scope to content rendered in a body portal. */
export const BeautifulUIPortalRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIPortalRoot.displayName = "BeautifulUIPortalRoot";

export default BeautifulUIRoot;

